local function initMaxSDK()
    local kTool = CS.Engine.Lib.KTool
    if kTool.UNITY_ANDROID() or kTool.UNITY_IOS() then
        local AdConfig = import('Game.Entry.AdConfig')
        local bundleId = CS.UnityEngine.Application.identifier
        if AdConfig.iOS[bundleId] and type(typeof(CS.FMaxSdkApp)) == 'userdata' then
            ---@type FMaxSdkApp
            local maxSdkApp = kTool.GetOrAddComponent(CS.Game.Native.Game.Instance.gameObject, typeof(CS.FMaxSdkApp))
            maxSdkApp.onSuccess = function(event)
                if event == 'OnRewardedAdLoadedEvent' then
                    -- reward ad load success
                end
                Events.Broadcast("AD_EVENT", event)
            end
            if not maxSdkApp.IsSdkInitialized then
                if kTool.UNITY_IOS() then
                    if AdConfig.iOS[bundleId] then
                        maxSdkApp:InitializeWithUnitId(AdConfig.iOS[bundleId].inter,AdConfig.iOS[bundleId].reward)
                    end
                else
                    if AdConfig.Android[bundleId] then
                        maxSdkApp:InitializeWithUnitId(AdConfig.Android[bundleId].inter,AdConfig.Android[bundleId].reward)
                    end
                end
            end
        end
    end
end

function XMainHome:Awake()
    initMaxSDK()
    ---兼容问题强制刷新一次cache值
    sceneManagement:UpdateCache()
    self._eventHandlerMap = {
        [Constants.EventNames.ScreenBackEvent] = Events.AddListener(Constants.EventNames.ScreenBackEvent, Bind(self, self.BackToMainHomeAction)),
        [Constants.EventNames.UIMainHomeSceneFocusShowEventName] = Events.AddListener(Constants.EventNames.UIMainHomeSceneFocusShowEventName, Bind(self, self.SetHomeMainSceneFocus)),
        [Constants.EventNames.UIMainHomeSceneFocusGrowSceneEventName] = Events.AddListener(Constants.EventNames.UIMainHomeSceneFocusGrowSceneEventName, Bind(self, self.SetFocusGrowScene)),
        [Constants.EventNames.RoleLoadComplete] = Events.AddListener(Constants.EventNames.RoleLoadComplete, Bind(self, self.OnRoleLoadCompleteEvent)),
        [Constants.EventNames.RoleTouchable] = Events.AddListener(Constants.EventNames.RoleTouchable, Bind(self, self.OnRoleTouchableEvent)),
        [Constants.EventNames.HomeSceneShowSignboard] = Events.AddListener(Constants.EventNames.HomeSceneShowSignboard, Bind(self, self.ShowSignboard)),
    }
end

function XMainHome:BackToMainHomeAction()
