        self._loadingUI:Close()
        self._loadingUI = nil
    end
end

---OnRoleLoadCompleteEvent
---角色加载成功
---@param skinId number
function XMainHome:OnRoleLoadCompleteEvent(skinId)
    self._roleLoadSkinId = skinId
    if isNull(UIModule.CurrentScreen:LastDialog()) or UIModule.CurrentScreen:LastDialog().Argument.id == Constants.UITypeIds.UIHomeView then
        local cardDojo = self:OnRoleTouchableEvent(true)
        if cardDojo then
            Events.Broadcast(Constants.EventNames.UIEventHomeRoleQuickTapAction, { playerCardId = cardDojo.id, cardId = cardDojo.cardId, skinId = checkNumber(self._roleLoadSkinId) })
        end
    end
end

--- 是否可让角色交互
---@param isTouchable boolean
function XMainHome:OnRoleTouchableEvent(isTouchable)
    ---@type PlayerComponent
    local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    if playerComponent then
        ---@type CardDojo
        local cardDojo = playerComponent:GetSignboardCardDojo()
        if self._roleLoadSkinId == checkNumber(cardDojo.cardSkin) then
            ---@type CardProgressionUtils
            local CardProgressionUtils = import("Game.CardProgression.CardProgressionUtils")
            ---@type CardProgressionControllerRole
            local env = CardProgressionUtils.GetRoleControllerEnv()
            if env then
                ---加载看板娘
                local state = checkNumber(CfUtils.GetLocalData(Constants.UICacheDataKeys.HOME_BOARD_STATE, '1'))
                local go
                if state == ModelType.Role then
                    go = env:GetRoleBySkinId(self._roleLoadSkinId)
                elseif state == ModelType.Cat then
                    go = env:GetCatBySkinId(self._roleLoadSkinId)
                end
                if not isNull(go) then
                    ---@type HedgehogTeam.EasyTouch.QuickTap
                    local quickTap = KTool.GetOrAddComponent(go, QuickTapType)
                    quickTap.onTap:RemoveAllListeners()
                    if isTouchable then
                        self:CatAddCollider(go, state)
                        quickTap.onTap:AddListener(function(gesture)
                            if not isNull(UIModule.CurrentScreen:LastDialog()) and UIModule.CurrentScreen:LastDialog().Argument.id == Constants.UITypeIds.UIHomeView then
                                Events.Broadcast(Constants.EventNames.UIEventHomeRoleQuickTapAction, { playerCardId = cardDojo.id, cardId = cardDojo.cardId, skinId = checkNumber(self._roleLoadSkinId) })
                            end
                        end)
                    end
                end
            end
            return cardDojo
        end
    end
end

