function XMainHome:SetSceneActive(isActive)
    self._isShowHomeScene = isActive
    ---自定义加载进度的逻辑在此处
    ---此处添加一个判断，当显示的时候相机的culling mask再copy一次对照
    if isActive then
        ----@type UnityEngine.Camera
        -- local camera = KTool.FindCameraForLayer(CS.UnityEngine.LayerMask.NameToLayer("role_shadowcaster"))
        -- if isNull(camera) then
            ----说明不存在这个层的相机，要设置一次
            ---@type SceneInstance
            local sceneIns = sceneManagement:GetSceneInstance(self.sceneId)
            local cameraOrigin = sceneIns:GetCacheObjectByName('Camera')
            if cameraOrigin then
                local urpBase = cameraOrigin:GetComponent(typeof(URPBaseCamera))
                if urpBase then
                    -- print("[黑屏] home copy camera")
                    urpBase:CopyCamera()
                end
                -- 强制激活一次反射
                local reflection = cameraOrigin:GetComponent(typeof(PlanarReflections))
                if isNotNull(reflection) then
                    reflection:UpdateProperties()
                end
            end
        -- end
    end
    sceneManagement:SetActive(self.sceneId, isActive)
end

