function XMainHome:LoadEnterTimeAsync()
    ---@type SceneInstance
    local sceneIns = sceneManagement:GetSceneInstance(self.sceneId)
    local parentTrans = sceneIns:GetCacheObjectByName(CACHE_OBJECT_NAME.LOCATION)
    local homeLocation = parentTrans.transform:Find(CACHE_OBJECT_NAME.LOCATION_UP)
    ---@type PlayerComponent
    local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    if playerComponent then
        ---@type CardDojo
        local cardDojo = playerComponent:GetSignboardCardDojo()
        ---@type CardVo
        local cardVo = playerComponent:GetSignboardCardVo()
        ---@type CardConfMgr
        local cardConfMgr = CardConfMgr:GetInstance()
        ---@type CardSkinVo
        local cardSkinVo = cardConfMgr:GetCardSkinBySkinId(cardDojo.cardSkin)
        local loader = ResourceModule.LoadBundleAsync(string.format(RoleEnterPrefabPath, tostring(cardVo.characterId)))
        while not loader.IsSuccess do
            cs_coroutine.yield_return()
        end
        ---@type CardProgressionConstants
        local CardProgressionConstants = import("Game.CardProgression.CardProgressionConstants")
        local prefabPath = string.format(CardProgressionConstants.PrefabPath.CatLobbyPath, cardSkinVo.catPrefab)
        if not loader.IsError then
            local go = loader:Instantiate()
            print("cardSkinVo.catPrefab", cardSkinVo.catPrefab)
            go:SetActive(false)
            local catGo = GameUtils.LoadBundleAsync(prefabPath, go.transform:Find(CACHE_OBJECT_NAME.CAT_LOC), false)
            go.transform:SetParent(homeLocation.transform)
            CS.Engine.Lib.KTool.ResetTransform(go.transform)
            local playableDirector = KTool.GetComponent(go, typeof(PlayableDirector))
            playableDirector.playOnAwake = false
            local binder = go:AddComponent(typeof(CS.Game.Native.Timeline.TimelineBinder))
            binder:SetTrackDynamic(PLAYABLE_ENTER_NAME.CAT_ANIMATOR, catGo)
            binder:SetTrackDynamic(PLAYABLE_ENTER_NAME.CAT_OBJECT, catGo)
            self._timelinePlayable = playableDirector
            self.timelineNotificationReceiver = KTool.GetOrAddComponent(playableDirector.gameObject, typeof(TimelineNotificationReceiver))
            self.__ProcessNotify = Bind(self, self.ProcessNotify)
            self.timelineNotificationReceiver:CustomOnNotify("+", self.__ProcessNotify)
        end
        loader:Release()
        loader = nil
    end
end

function XMainHome:ProcessNotify(origin, notification, context)
    local notifyType = notification:GetType()
    print("ProcessNofity", notifyType)
    if notifyType == typeof(CS.Markers.UIActiveMarker) then
        ---然后删除timeline显示角色对象
        KCookie.Set("IS_WAITING_PLAY_TIME_LINE", 1)
        UIModule.OpenDialog(UIArgs(Constants.UITypeIds.UIHomeView))
        Events.Broadcast(Constants.EventNames.HomeSceneRoleActive, true, false)
    end
    self.timelineNotificationReceiver:CustomOnNotify("-", self.__ProcessNotify)
    self.__ProcessNotify = nil
end

function XMainHome:PlayEnterTimeLine()
    if not isNull(self._timelinePlayable) then
        ---@type UnityEngine.Playables.PlayableDirector
        local timelinePlayable = self._timelinePlayable
        KTool.SetActive(timelinePlayable.gameObject, true)
        timelinePlayable:Play()
        KCookie.Set(IS_FIRST_ENTER_HOME_SCENE, 1)
        CfUtils.ChangeMainCamDefalultBlend(0.5)
        cs_coroutine.start(function()
            cs_coroutine.yield_return(Yielders.GetWaitForSeconds(timelinePlayable.duration - 1.7))
            local mainCameraGo = self._mainCameraGo
            KTool.SetActive(mainCameraGo, true)
            UICommonUtils.WaitBrainBlendingComplete()
            cs_coroutine.yield_return(Yielders.GetWaitForSeconds(1.3))
            KTool.SetActive(self._timelinePlayable.gameObject, false)
            CfUtils.ChangeMainCamDefalultBlend(0)
            ---执行角色的显示timeline入场的逻辑
            if not isNull(self._timelinePlayable) then
                KTool.SafeDelete(self._timelinePlayable.gameObject, true)
                self._timelinePlayable = nil
            end
            ---@type CardProgressionUtils
            local CardProgressionUtils = import("Game.CardProgression.CardProgressionUtils")
            ---@type CardProgressionControllerRole
            local env = CardProgressionUtils.GetRoleControllerEnv()
            if not isNull(env) then
                ---@type PlayerComponent
                local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
                if playerComponent then
                    ---@type CardDojo
                    local cardDojo = playerComponent:GetSignboardCardDojo()
                    local go = env:GetRoleBySkinId(cardDojo.cardSkin)
                    if not isNull(go) then
                        local animator = KTool.GetComponent(go, typeof(Animator))
                        if not isNull(animator) then
                            animator:SetTrigger("isSwitch")
                        end
                    end
                end
            end
        end)
    else
        KCookie.Set(IS_FIRST_ENTER_HOME_SCENE, 1)
        cs_coroutine.start(function()
            local mainCameraGo = self._mainCameraGo
            KTool.SetActive(mainCameraGo, true)
            ---然后删除timeline显示角色对象
            Events.Broadcast(Constants.EventNames.HomeSceneRoleActive, true, false)
            ---第一次进入
            coroutine.yield(UIModule.OpenDialog({ id = Constants.UITypeIds.UIHomeView }))
        end)
    end
end

