end

function XMainHome:AsyncLoadingResources()
    coroutine.yield(UINavigationBarRoot.Instance:Show()) --//显示通用返回条的逻辑
    ---可能是设置中退出再进的情况，需要再显示一次
    UINavigationBarRoot.Instance:SetActive(true)
    UINavigationBarRoot.Instance:SetInfoTipButtonState(false)--标题也要设置为不显示
    CfUtils.SetTopCommonActive(false, true)

    local toProgress = 100

    self:InitHomeLoadingProgress(self._loadingUI)

    ---加载主界面场景如果是第一次进入的时候同步加载
    local sceneData = sceneManagement:GetScenePathInfo(self.sceneId)
    local isCached = checkNumber(KCookie.Get(Constants.UICacheDataKeys.OVERSEA_MANAGER_SCENE_STATE))
    if isCached == 0 then
        if not QTEShow then
            sceneManagement:Transition({ identifier = sceneData.id, isCache = true })
            while sceneManagement:IsTransition() do
                self.displayProgress = self.displayProgress + 0.6
                if self._loadingUI then
                    self._loadingUI:__Progress(self.displayProgress * 0.01)
                end
                coroutine.yield(Yielders.EndOfFrame)
            end
        end
    end

    local sceneInstance = sceneManagement:GetSceneInstance(sceneData.id)
    --一个动态节点， 解决从战斗回来的界面load一个3d物体时会创建到战斗场景里随着战斗场景一起被销毁
    if not isNull(sceneInstance) then
        sceneInstance:RemoveCacheObjectByName("DynamicNode")
    end

    if Config.DEBUG_QUICK_START then
        self.displayProgress = toProgress
        --self.LoadEnterTimeAsync = function(_)
        --    return Yielders.EndOfFrame
        --end
        if self._loadingUI then
            self._loadingUI.PlayAndWaitFinish = function(_)
                return Yielders.EndOfFrame
            end
        end
    end

    local isFirstStartGame = checkNumber(KCookie.Get('isFirstStartGame'))
    if isFirstStartGame == 0 then
        local ActivityMgr = import('Game.Activity.ActivityMgr'):GetInstance()
        ActivityMgr:UpdateActivityHomeData()
        ---加载timeline
        --cs_coroutine.yield_return(self:LoadEnterTimeAsync())

        -- 请求钓鱼数据（新加了解锁条件29 钓鱼解锁，需要用到钓鱼数据。所以一进游戏先请求一下数据保存起来）
        local fishComp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.FishingComponent)
        fishComp:FishingCollectionReq()
    end

    self:InitHomeSceneCache()

    ---@type CardProgressionUtils
    local CardProgressionUtils = import("Game.CardProgression.CardProgressionUtils")
    ---@type CardProgressionControllerRole
    local env = CardProgressionUtils.GetRoleControllerEnv()
    env:InitNode(self._isShowGrowScene)

    self:SetHomeMainSceneFocus(true)
    -- self:ShowSignboard()
    if not isNull(sceneInstance) then
        local lightGo = sceneInstance:GetCacheObjectByName("Chara Light")
        if not isNull(lightGo) then
            AddLuaBehaviour(lightGo, 'Game.Main.HomeCharaLight')
        end
    end
    if isCached == 0 then
        if self.displayProgress < toProgress then
            while self.displayProgress < toProgress do
                self.displayProgress = self.displayProgress + 2
                if self._loadingUI then
                    self._loadingUI:__Progress(self.displayProgress * 0.01)
                end
                coroutine.yield(Yielders.EndOfFrame)
            end
        end
    else
        KCookie.Set(Constants.UICacheDataKeys.OVERSEA_MANAGER_SCENE_STATE, 0)
    end


    --第一次进来
    if isFirstStartGame == 0 and not QTEShow then
        cs_coroutine.yield_return(self._loadingUI:PlayAndWaitFinish())
        self._loadingUI:Close()
        self._loadingUI = nil
        local isFirstEnterHome = checkNumber(KCookie.Get(IS_FIRST_ENTER_HOME_SCENE))
        if isFirstEnterHome == 0 then
            print("PlayEnterTimeLine")
            self:PlayEnterTimeLine()
        end
    else
        if self._loadingUI then
            self._loadingUI:Close()
        end
        self._loadingUI = nil
    end

    while checkNumber(KCookie.Get('QTEShow')) == 1 do
        coroutine.yield(CS.UnityEngine.WaitForSeconds(0.2))
    end

    printInfo("main home ok")
    local isMainGuideFinish = checkNumber(KCookie.Get("MainGuideFinish")) == 1
    if isMainGuideFinish then
        KCookie.Set("MainGuideFinish", 0)
        return
    end

    --游戏开始后的互斥主界面 不打开
    if isFirstStartGame == 0 then
        local IsOpenGuide = AppEngine.GetConfig("Engine.Dev", "IsOpenGuide")
        if checkNumber(IsOpenGuide) == 1 then
            ---@type GuideComponent
            local guideComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.GuideComponent)
            if guideComp:GetCompleteModuleId() <=  Constants.GuideModule.MainQuest1_1 then
                ---加个协程 是因为 可能 引导检查正好到检查屏蔽层了
                cs_coroutine.start(function()
                    ---修复翻转导致引导第一步未执行完成 进而导致的卡死
                    if guideComp:GetCompleteModuleId() < 1 then
                        while not guideComp:CheckCurModuleIsCompleteStep(1) do
                            cs_coroutine.yield_return()
                        end

                    end
                    ---触发第二步引导
                    guideComp:SetIsForcedTrigger(true)

                end)

                return
            end
        end
    else
        ---如果是从战斗中出来时需要更新背景音乐
        ---@type CriWareUtils
        local CriWareUtils = import('Game.Entry.CriWareUtilsFix')
        CriWareUtils.PlayRandomBGMFromCDList()
    end
end

function XMainHome:InitHomeSceneCache()
    ---@type SceneInstance
    local sceneIns = sceneManagement:GetSceneInstance(self.sceneId)
    local rootTransform = sceneIns:GetCacheObjectByName(CACHE_OBJECT_NAME.VIRTUAL_CAMERA_ROOT).transform
    local mainCameraGo = rootTransform:Find(CACHE_OBJECT_NAME.HOME).gameObject
    --local mainCameraCultivateGo = rootTransform:Find(CACHE_OBJECT_NAME.CULTIVATE).gameObject

    self._mainCameraGo = mainCameraGo
    --self._mainCameraCultivateGo = mainCameraCultivateGo

    local IdolLive3D_Loader = import('Game.IdolLive3D.IdolLive3D_Loader')
    IdolLive3D_Loader.AppendedScene()
end

---ShowSignboard
---加载人物的逻辑
---@param cardDojo CardDojo
---@param cameraState number
---@param signboardState number
function XMainHome:ShowSignboard(cardDojo, cameraState, signboardState)
    ---加载看板娘
    local state = signboardState or checkNumber(CfUtils.GetLocalData(Constants.UICacheDataKeys.HOME_BOARD_STATE, '1'))
    local isFirstShowSignboard = false
    if isNull(cardDojo) then
        ---@type PlayerComponent
        local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
        if playerComponent then
            cardDojo = playerComponent:GetSignboardCardDojo()
        end
        isFirstShowSignboard = true
    end
    ---@type CardProgressionUtils
    local CardProgressionUtils = import("Game.CardProgression.CardProgressionUtils")
    ---@type CardProgressionControllerRole
    local env = CardProgressionUtils.GetRoleControllerEnv()
    local isFirstEnterHome = checkNumber(KCookie.Get(IS_FIRST_ENTER_HOME_SCENE))
    -- env:InitNode(self._isShowGrowScene)
    if isFirstEnterHome == 0 then
        env:OnEventCultivateRoleActiveAction(false, false)
    end
    local go
    if not isNull(env) then
        --print('---->>', state)
        if state == ModelType.Role then
            env:LoadRole(cardDojo.cardSkin, true, { cameraState or CardProgressionConstants.CameraState.HomeFull }, nil, cardDojo)
            go = env:GetRoleBySkinId(cardDojo.cardSkin)
            CfUtils.WriteLocalData(Constants.UICacheDataKeys.HOME_BOARD_STATE, "1")
        elseif state == ModelType.Cat then
            local awakeningLevel = checkNumber(cardDojo.awakeningLevel)
            env:LoadCat(cardDojo.cardSkin, { cameraState or CardProgressionConstants.CameraState.HomeRoleToCat, awakeningLevel }, true)
            go = env:GetCatBySkinId(cardDojo.cardSkin)
            CfUtils.WriteLocalData(Constants.UICacheDataKeys.HOME_BOARD_STATE, "2")
        elseif state == ModelType.Cover then
            env:LoadExtraScene(cardDojo.cardSkin)
            env:FreshCameraStateByParams({CardProgressionConstants.CameraState.CultivateRoleAndCatHide}, nil, true)
            ----再改下镜头
            ---@type CardPositionVo
            local positionVo = CardConfMgr:GetInstance():GetCardPosByCardId(cardDojo.cardId, cardDojo.cardSkin)
            local position = positionVo.mainRoleStance
            local rotation = positionVo.mainRoleDirection
            local cameraTrans = env:GetCultivateCameraTrans()
            cameraTrans.localPosition = position
            cameraTrans.localRotation = Quaternion.Euler(rotation.x, rotation.y, rotation.z)
            CfUtils.WriteLocalData(Constants.UICacheDataKeys.HOME_BOARD_STATE, "3")
            if isFirstShowSignboard then
                ---第一次进入并且是立绘的时候要强刷新下页面
                Events.Broadcast(Constants.EventNames.UIEventHomeRoleQuickTapAction, { playerCardId = cardDojo.id, cardId = cardDojo.cardId, skinId = checkNumber(cardDojo.cardSkin) })
            end
        end
        if not isNull(go) then
            ---@type HedgehogTeam.EasyTouch.QuickTap
            local quickTap = KTool.GetOrAddComponent(go, QuickTapType)
            self:CatAddCollider(go, state)
            quickTap.onTap:RemoveAllListeners()
            quickTap.onTap:AddListener(function(gesture)
                Events.Broadcast(Constants.EventNames.UIEventHomeRoleQuickTapAction, { playerCardId = cardDojo.id, cardId = cardDojo.cardId, skinId = checkNumber(cardDojo.cardSkin) })
            end)
        end
        ---@type Engine.UI.UILuaDialog
        local homeDialog = UIModule.CurrentScreen:GetDialog(Constants.UITypeIds.UIHomeView)
        if homeDialog then
            ---@type UIHomeMain
            local homeEnv = homeDialog.Env
            -- if state == ModelType.Cover then
                -- Events.Broadcast(Constants.EventNames.HomeSceneRoleActive, false, false)
            -- end
            if homeEnv then
                homeEnv:ShowAndFreshCover(state, cardDojo.cardSkin)
            end
        end
    end
end

function XMainHome:CatAddCollider(go, state)
    if state == ModelType.Cat then
        ---@type UnityEngine.SphereCollider
        local collider = KTool.GetOrAddComponent(go, typeof(CS.UnityEngine.SphereCollider))
        collider.center = Vector3.New(0, 0.2, 0)
        collider.radius = 0.3

    end
end

function XMainHome:OnInitialize()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        local isBackToHomeScene = checkNumber(KCookie.Get('BackToHomeScene')) == 1
        KCookie.Set('BackToHomeScene', 0)
        self.isBackToHomeScene = isBackToHomeScene
        ---计算一下设置中是否存在绑定手机相关的小红点
        if GameUtils.IsUnlockedBySystemTogId(Constants.SystemToggleIds.Id277) then
            ---@type SDKService
            local sdkService =  import('Game.Entry.SDKService'):GetInstance()
            if sdkService:IsForeignSDK() or KTool.UNITY_EDITOR() then
                ---邮箱解锁了
                ---@type UserComponent
                local userComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.UserComponent)
                local mail = userComp.userInfo.email
                local date = require('Frame.date')
                local now = date()
                local showRedPoint = false
                local strDate = CfUtils.GetLocalData("BIND_EMAIL", "")
                if not string.isEmpty(strDate) then
                    local pre = date(strDate)
                    --print("===>>", now:fmt(), date.diff(now, pre):getday())
                    if date.diff(now, pre):getday() >= 7 then
                        showRedPoint = true
                    end
                else
                    showRedPoint = true
                end
                --print("===>>", userComp.userInfo.bindTerminalRewards, showRedPoint)
                if string.isEmpty(mail) and showRedPoint and checkInt(userComp.userInfo.bindTerminalRewards) == 0 then
                    GameUtils.SetRedPointNum(Constants.RedPointConst.OtherSettingEmailButton, 1)
                    GameUtils.InvokeRedPointCallBack(Constants.RedPointConst.OtherSettingEmailButton)
                end
            end
        end
    end
    ))
    return coWait
end

