function XMainHome:OnFinalize()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()

        local IdolLive3D_Loader = import('Game.IdolLive3D.IdolLive3D_Loader')
        IdolLive3D_Loader.UnloadAppendedScene()

        if not isNull(self._timelinePlayable) then
            KTool.SafeDelete(self._timelinePlayable.gameObject, true)
            self._timelinePlayable = nil
        end
        self._loadingUI = nil

        for eventName, eventHandler in pairs(self._eventHandlerMap or {}) do
            Events.RemoveListener(eventName, eventHandler)
        end
        self._eventHandlerMap = nil

        CS.UnityEngine.LightmapSettings.lightProbes = nil
        KCookie.RemoveAllListener(Constants.UICacheDataKeys.MainSceneActiveState)
        KCookie.RemoveAllListener(Constants.UICacheDataKeys.MainSceneID)
        local isCached = checkNumber(KCookie.Get(Constants.UICacheDataKeys.OVERSEA_MANAGER_SCENE_STATE))
        if isCached == 0 then
            local sceneInstance = sceneManagement:GetSceneInstance(self.sceneId)
            if sceneInstance then
                coroutine.yield(sceneManagement:UnloadScene(sceneInstance))
            end
        else
            --self:SetFocusGrowScene(false)
            self:SetSceneActive(false)
        end
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

return XMainHome
